#![allow(unused_imports)]
use vstd::prelude::*;

verus! {
    /// Given two arrays `a` and `b` of 8-bit signed integers of equal length,
    /// returns a boolean array `result` of the same length such that for every
    /// index `i`, `result[i]` is true iff `a[i] as i32 > b[i] as i32`.
    fn greater(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            // The output has the same length as the inputs
            result.len() == a.len(),
        ensures
            // At each index i, the result indicates whether a[i] > b[i] (in i32)
            forall |i: usize| i < a.len() ==>
                result[i] == ((a[i] as i32) > (b[i] as i32))
    {
        let mut result = Vec::<bool>::new();
        let mut i: usize = 0;

        // We build up `result` one element at a time
        while i < a.len()
            invariant
                // We've pushed exactly `i` elements so far
                result.len() == i,
            invariant
                // For all indices j < i, result[j] is correct
                forall |j: usize| j < i ==>
                    result[j] == ((a[j] as i32) > (b[j] as i32)),
            decreases
                // We make progress by increasing i toward a.len()
                a.len() - i
        {
            let ai: i8 = a[i];
            let bi: i8 = b[i];
            // Compare in i32 to avoid overflow subtleties
            let cmp: bool = (ai as i32) > (bi as i32);
            result.push(cmp);
            i += 1;
        }

        result
    }
}